// GENERATED by scripts/build-courses.ts from src/lib/courses/content — edit those files, then run: npm run courses
import type { LessonText } from '../types';
const text: LessonText[][] = [[{"say":"Mechanics describes how things move and why. Calculus makes it precise.","blocks":[{"t":"key","text":"Velocity v = dx/dt and acceleration a = dv/dt. For constant acceleration: v = v₀ + at, x = x₀ + v₀t + ½at², v² = v₀² + 2aΔx. Projectiles: horizontal velocity is constant; vertical acceleration is −g (9.8 m/s²)."},{"t":"p","text":"Newton's laws: (1) inertia; (2) F_net = ma (vector sum of forces); (3) equal and opposite force pairs. Draw free-body diagrams."},{"t":"p","text":"Forces: weight mg, normal force, tension, friction (f_s ≤ μ_sN, f_k = μ_kN), springs F = −kx. Uniform circular motion: a = v²/r toward the center."},{"t":"ex","problem":"A 5 kg box is pulled with 30 N on a surface with friction force 10 N. Find its acceleration.","steps":["F_net = 30 − 10 = 20 N","a = 20 ÷ 5"],"answer":"4 m/s²"},{"t":"lab","kind":"lab","title":"Atwood machine","aim":"Hang two masses over a light pulley and measure the acceleration.","sets":[{"name":"m2","start":1.2,"label":"Heavier mass (kg)","min":1,"max":3,"step":0.05},{"name":"m1","start":1,"label":"Lighter mass (kg)","min":0.5,"max":1,"step":0.05}],"outs":[{"name":"a","expr":"(m2 - m1)*g/(m1 + m2)","label":"Acceleration (m/s²)"},{"name":"T","expr":"2*m1*m2*g/(m1 + m2)","label":"String tension (N)"}],"steps":["Record the acceleration for 5 values of the heavier mass.","Use your data to estimate g."],"noise":3,"result":"a = (m₂ − m₁)g/(m₁ + m₂): only the difference in weight drives the system, but both masses must be accelerated. With nearly equal masses the motion is slow enough to time, which is how Atwood measured g.","plot":{"x":"m2","y":"a"}}]},{"say":"Energy and momentum are conserved, which makes many hard problems simple.","blocks":[{"t":"key","text":"Work W = ∫F·dx (= Fd cos θ for constant force). Kinetic energy K = ½mv²; the work–energy theorem: W_net = ΔK. Potential energy: gravitational U = mgh, spring U = ½kx². With only conservative forces, mechanical energy is conserved. Power P = dW/dt."},{"t":"p","text":"Momentum p = mv; impulse J = FΔt = Δp. In isolated systems total momentum is conserved. Elastic collisions also conserve kinetic energy; inelastic ones don't (perfectly inelastic: objects stick together)."},{"t":"ex","problem":"A 2 kg cart at 3 m/s hits and sticks to a 1 kg cart at rest. Find the final speed.","steps":["Momentum: 2 × 3 = (2 + 1)v"],"answer":"v = 2 m/s"}]}],[{"say":"Spinning objects follow rules parallel to straight-line motion.","blocks":[{"t":"key","text":"Angular quantities: θ, ω = dθ/dt, α = dω/dt; v = rω. Torque τ = rF sin θ; τ_net = Iα, where moment of inertia I = Σmr² depends on mass distribution. Rotational KE = ½Iω². Angular momentum L = Iω is conserved without external torque (a skater pulling in arms spins faster)."},{"t":"p","text":"Gravitation: F = Gm₁m₂/r². Orbits: circular orbital speed v = √(GM/r); Kepler's third law T² ∝ r³. Gravitational potential energy U = −GMm/r."},{"t":"tip","text":"Every linear formula has a rotational twin: swap x for θ, v for ω, a for α, m for I, F for τ, and p for L."}]},{"say":"Springs, pendulums, sound and light all share the mathematics of oscillation.","blocks":[{"t":"key","text":"Simple harmonic motion: x(t) = A cos(ωt + φ). For a mass on a spring ω = √(k/m), T = 2π√(m/k); for a small-angle pendulum T = 2π√(L/g). Energy sloshes between kinetic and potential."},{"t":"p","text":"Waves: v = fλ. Transverse versus longitudinal. Wave speed on a string v = √(T/μ). Superposition gives interference: constructive (in phase) and destructive. Standing waves on a string: λ = 2L/n. Doppler effect: approaching sources sound higher."},{"t":"ex","problem":"A wave has frequency 50 Hz and wavelength 4 m. Find its speed.","steps":["v = fλ = 50 × 4"],"answer":"200 m/s"},{"t":"lab","kind":"lab","title":"Driven oscillator and resonance","aim":"Drive a mass on a spring (natural frequency 10 rad/s) at different frequencies and measure the amplitude.","sets":[{"name":"w","start":8,"label":"Driving frequency (rad/s)","min":1,"max":20,"step":0.25},{"name":"b","start":1,"label":"Damping (kg/s)","min":0.2,"max":5,"step":0.1}],"outs":[{"name":"A","expr":"10/sqrt((100 - w^2)^2 + (b*w)^2)","label":"Amplitude (m)"}],"steps":["Record the amplitude at 6 driving frequencies.","Increase the damping and compare the peak."],"noise":2,"result":"The amplitude peaks sharply when the driving frequency matches the natural frequency: resonance. More damping lowers and widens the peak. Engineers add damping so bridges and buildings don't resonate.","plot":{"x":"w","y":"A"}}]}],[{"say":"Electric charges create fields, and moving charges make circuits work.","blocks":[{"t":"key","text":"Coulomb's law F = kq₁q₂/r². Electric field E = F/q; potential V = U/q, with E = −dV/dx. Gauss's law relates flux to enclosed charge. Capacitance C = Q/V; energy stored ½CV²."},{"t":"p","text":"Circuits: current I = dQ/dt, Ohm's law V = IR, power P = IV = I²R. Series resistors add; parallel resistors combine as 1/R = 1/R₁ + 1/R₂. Kirchhoff's rules: the junction rule (charge conservation) and the loop rule (energy conservation). RC circuits charge with time constant τ = RC."},{"t":"ex","problem":"Find the equivalent resistance of 6 Ω and 3 Ω in parallel.","steps":["1/R = 1/6 + 1/3 = 1/2"],"answer":"2 Ω"},{"t":"lab","kind":"lab","title":"Battery internal resistance","aim":"Connect different load resistors to a 9 V battery with 1.5 Ω internal resistance and measure the terminal voltage and power.","sets":[{"name":"Rl","start":5,"label":"Load resistance (Ω)","min":0.1,"max":20,"step":0.1},{"name":"r","start":1.5,"label":"Internal resistance (Ω)","min":0.5,"max":5,"step":0.5}],"outs":[{"name":"I","expr":"9/(Rl + r)","label":"Current (A)"},{"name":"V","expr":"9 - I*r","label":"Terminal voltage (V)"},{"name":"P","expr":"I^2*Rl","label":"Power to load (W)"}],"steps":["Record the voltage and power for at least 6 loads.","Find the load that receives the most power."],"noise":2,"result":"The terminal voltage drops below the emf as current flows (V = ε − Ir). Power delivered to the load is greatest when the load resistance equals the internal resistance (maximum power transfer).","plot":{"x":"Rl","y":"P"}}]},{"say":"Magnetism and electricity are one force, and at small scales classical physics gives way to quantum rules.","blocks":[{"t":"key","text":"Magnetic force on a charge F = qv × B and on a wire F = IL × B. Currents create magnetic fields (Ampère's law). Faraday's law: a changing magnetic flux induces an emf, ε = −dΦ/dt; Lenz's law gives the direction opposing the change. This drives generators and transformers. Maxwell's equations unify E and B; light is an electromagnetic wave."},{"t":"p","text":"Modern physics: photon energy E = hf; the photoelectric effect shows light comes in quanta. Matter has wavelength λ = h/p. Atoms have discrete energy levels. Special relativity: time dilation, length contraction, E = mc². Nuclear decay follows half-lives."}]}]];
export default text;
